public class AveragerCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Averager impl) {
        try {
            return AveragerChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectAverager()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectAverager()));
        check("rejects the integer-division bug", false, verdict(new IntegerDivisionAverager()));
        check("rejects the crash-on-empty-array bug", false, verdict(new CrashOnEmptyAverager()));
        check("rejects the off-by-one summing bug", false, verdict(new OffByOneAverager()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectAverager implements Averager {
    public double average(int[] values) {
        if (values.length == 0) return 0.0;
        int sum = 0;
        for (int v : values) sum += v;
        return (double) sum / values.length;
    }
}

class AlsoCorrectAverager implements Averager {
    public double average(int[] values) {
        double total = 0.0;
        for (int i = 0; i < values.length; i++) total += values[i];
        return values.length == 0 ? 0.0 : total / values.length;
    }
}

class IntegerDivisionAverager implements Averager {
    public double average(int[] values) {
        if (values.length == 0) return 0.0;
        int sum = 0;
        for (int v : values) sum += v;
        return sum / values.length;
    }
}

class CrashOnEmptyAverager implements Averager {
    public double average(int[] values) {
        int sum = values[0];
        for (int i = 1; i < values.length; i++) sum += values[i];
        return (double) sum / values.length;
    }
}

class OffByOneAverager implements Averager {
    public double average(int[] values) {
        if (values.length == 0) return 0.0;
        int sum = 0;
        for (int i = 0; i < values.length - 1; i++) sum += values[i];
        return (double) sum / values.length;
    }
}

