/**
 * TASK: Write the checks that decide whether an Averager is correct.
 *
 * The Averager contract:
 *   average(values) returns the arithmetic mean of the values as a double.
 *   average on an EMPTY array returns 0.0.
 *   Examples: average({1, 2}) -> 1.5, average({2, 4}) -> 3.0, average({}) -> 0.0
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs -- a mean that is not a whole number, an empty array, a single value,
 * and negative values.
 */
interface Averager {
    /* Provided -- do not edit. */
    double average(int[] values);
}

public class AveragerChecker {

    public static boolean isCorrect(Averager impl) {
        try {
            if (!close(impl.average(new int[] {2, 4}), 3.0)) return false;
            if (!close(impl.average(new int[] {1, 2}), 1.5)) return false;
            if (!close(impl.average(new int[] {5}), 5.0)) return false;
            if (!close(impl.average(new int[] {}), 0.0)) return false;
            if (!close(impl.average(new int[] {-4, -1}), -2.5)) return false;
            if (!close(impl.average(new int[] {10, 20, 31}), 61.0 / 3.0)) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }

    private static boolean close(double actual, double expected) {
        return Math.abs(actual - expected) < 0.000001;
    }
}
